{
  "name": "loss_logsigmoid_advantage_gap_scaled_001_fixed_v2",
  "intuition": "Clamp scaled advantage_gap for numerical stability before applying logsigmoid; ensure adv_gap depends on log_prob_w for gradient tracking; compute weighted mean loss.",
  "pseudocode": "loss = -logsigmoid(clamp(scale * adv_gap, -20, 20)) weighted_mean",
  "hyperparams": {
    "scale": "4.0",
    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": ["logsigmoid", "clamp", "mul", "mean", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch[\"log_prob_w\"].float()\n    lpl = batch[\"log_prob_l\"].float()\n    weight = batch[\"weight\"].float()\n    adv_gap = batch[\"advantage_gap\"].float()\n    # Force adv_gap to depend on lpw for grad tracking safely\n    adv_gap = adv_gap + (lpw - lpw.detach()) * 0.0\n    scale = float(extra.get(\"hyperparams\", {}).get(\"scale\", 4.0))\n    x = ops.mul(scale, adv_gap)\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    loss = ops.mul(loss, weight)\n    return loss.mean()"
}
